// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length == 1);
        vm.assume(from != address(0));
        vm.assume(tos[0] != address(0));
        Reverter reverter = new Reverter();
        bool ok = false;
        try c.transfer(from, address(reverter), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "C should revert when callee reverts");
    }
}
contract Reverter { fallback() external payable { revert(); } }
